const CARD_DRAG_JS = phone => `const others = db.decks().filter(d => d.id !== dk.id), trayOpen = !!this.props.trayOpen;
  const cardDrag = {
    dragKey, dragList, trayShow: trayOpen ? 'flex' : 'none',
    tray: others.map((d, i) => ({ id: d.id, name: d.name, base: this.gen(d.seed + (d.round ? ' #' + d.round : ''), d.style).base, bg: trayOpen && !i ? t.text : t.surf, fg: trayOpen && !i ? t.bg : t.text })),
    grab: e => this.drag(e, { drops: ['deck:'], tray: others.length > 0, ink: t.text, bg: t.bg, lifted: liftRow, bottom: ${phone ? 92 : 0}, start: () => this.state.tagMenuOpen && this.setState({ tagMenuOpen: false }),
      drop: (id, w) => (w.to ? db.act.moveCard(id, w.to.slice(5)) : db.act.reorderCard(id, w.before)) }) };`;
const deckLogic = `
constructor(props) { super(props); this.state = { filter: 'All', tagMenuOpen: false, tagQ: '', q: '' }; }
renderVals() {
  ${T}${DB_JS}${COVER_LOGIC}${DECK_MATERIALS_JS}
  ${LIFT_JS}
  ${CARD_DRAG_JS(false)}
  ${DECK_MENUS_JS(false)}
  const labels = ['All', 'Basic', 'Fill in the blank', 'Image', 'Audio'];
  const f = this.state.filter, allRows = db.cards(dk.id), q = (this.state.q || '').trim().toLowerCase();
  const glyphs = { text: 'Aa', blank: '_', image: '▢', audio: '♪' };
  // Tags sit in one menu, so the filter row stays short however many tags the cards have.
  const uses = {}; allRows.forEach(r => r.tags.forEach(g => { uses[g] = (uses[g] || 0) + 1; }));
  const tagNames = Object.keys(uses).sort((a, b) => uses[b] - uses[a] || a.localeCompare(b));
  const tagOn = tagNames.includes(f), tq = (this.state.tagQ || '').trim().toLowerCase(), found = tagNames.filter(g => !tq || g.toLowerCase().includes(tq));
  const menuOpen = !!this.state.tagMenuOpen;
  // A row is the card: its icon, question and kind, answer, and when it's next (no tag chips, like the iPhone's, 2026-10-02; Tags ▾ filters).
  const rows = allRows.filter(r => (f === 'All' || r.kind === f || r.tags.includes(f)) && (!q || [r.front, r.back, ...r.tags].join(' ').toLowerCase().includes(q)))
    .map(r => ({ ...r, glyph: glyphs[r.icon], aiNote: r.ai ? ' · ' + r.ai : '', stateNote: r.pending ? ' · Waiting for you' : r.paused ? ' · Paused' : '' }));
  return {
    t, rows, ...chrome, ...coverVals, ...cardDrag, ...deckMenus, gs, vw, dg, query: this.state.q || '', setQuery: e => this.setState({ q: e && e.target ? e.target.value : '' }),
    filters: labels.map(l => ({ label: l, pressed: l === f ? 'true' : 'false', bg: l === f ? t.inv : t.surf, fg: l === f ? t.invText : t.text, pick: () => this.setState({ filter: l, tagMenuOpen: false }) })),
    tagBtn: { label: tagOn ? f : 'Tags', pressed: tagOn ? 'true' : 'false', bg: tagOn ? t.inv : t.surf, fg: tagOn ? t.invText : t.text, dot: tagOn ? tagCol(f) : 'transparent', dotW: tagOn ? '8px' : '0px' },
    tagMenu: { open: menuOpen, expanded: menuOpen ? 'true' : 'false', query: this.state.tagQ || '',
      toggle: () => this.setState({ tagMenuOpen: !menuOpen, tagQ: '', deckMenu: '' }), setQuery: e => this.setState({ tagQ: e && e.target ? e.target.value : '' }),
      rows: found.map(g => ({ ...tagChip(g), count: String(uses[g]), on: g === f, pressed: g === f ? 'true' : 'false', pick: () => this.setState({ filter: g === f ? 'All' : g, tagMenuOpen: false, tagQ: '' }) })), none: found.length === 0 }
  };
}`;

// The sample cell diagram (220 x 150). `pointer`: the "1" pointing at the nucleus; a picture with boxes has none.
// `sw`: its lines' width (thinner when it's drawn big).
const CELL = (w, h, pointer = true, sw = 2) => `<svg width="${w}" height="${h}" viewBox="0 0 220 150" fill="none" stroke="{{t.text}}" stroke-width="${sw}"${pointer ? '' : ' style="display: block;"'}><ellipse cx="104" cy="80" rx="94" ry="62"/><circle cx="116" cy="74" r="24" fill="{{t.surf}}"/><circle cx="120" cy="70" r="7" fill="{{t.text}}"/><ellipse cx="54" cy="96" rx="16" ry="8"/><ellipse cx="74" cy="46" rx="12" ry="6"/><ellipse cx="158" cy="112" rx="14" ry="7"/>${pointer ? '<path d="M138 60 L186 22"/><circle cx="194" cy="16" r="12" fill="{{t.inv}}" stroke="none"/><text x="194" y="21" text-anchor="middle" font-size="13" font-weight="700" fill="{{t.invText}}" stroke="none" font-family="Geist, sans-serif">1</text>' : ''}</svg>`;
// ---------- Image occlusion (the owner: "image mode for cards doesnt have way to add occlusion box") ----------
// An image card can hide parts of its picture behind boxes, and each box is its own card, like each blank of a
// fill-in-the-blank card. A box's place and size are fractions of the picture (0 to 1), so it fits the picture at any
// size, and each box has a label: what's under it, the answer. "What to hide": only the box being asked (the rest of
// the picture shows), or every box, with one asked.
// How the boxes look on a card (review, Cards to check, Learn, the practice test, and Live's big screen): every box that
// hides a part is yellow (the owner, 2026-10-02: "for hidden boxes can you make the box color yellow?"), one yellow that
// reads on a light picture and a dark one, with black numbers on it (OCC: the editor's boxes and the iPhone's are the
// same). The asked box has an edge inside it in the screen's own outline color (c.edge: black on a light card, white on a
// dark one), and in "Hide all" the others have softer numbers. Once the answer shows, its yellow fades and that edge stays
// as its outline, as before. `c` holds the screen's own colors: that edge, and the ring that sets the boxes off the
// picture (ring).
const OCC_JS = `const occView = (boxes, ask, mode, shown, c) => (boxes || []).map((b, i) => {
    const asked = i === ask, hide = asked || mode === 'all', pct = v => +(v * 100).toFixed(3) + '%';
    return { n: hide ? String(i + 1) : '', x: pct(b.x), y: pct(b.y), w: pct(b.w), h: pct(b.h), z: asked ? '2' : '1',
      bg: asked ? (shown ? 'transparent' : '${OCC.fill}') : hide ? '${OCC.fill}' : 'transparent', fg: asked ? (shown ? 'transparent' : '${OCC.ink}') : '${OCC.soft}',
      ring: asked ? 'inset 0 0 0 2.5px ' + c.edge + ', 0 0 0 2px ' + c.ring : hide ? '0 0 0 2px ' + c.ring : 'none',
      // Only showing the answer fades; covering a new card's box is instant, so its answer never shows through.
      tr: asked && shown ? 'background-color .45s cubic-bezier(.2,.8,.2,1), color .3s ease' : 'none' };
  });`;
const OCC_BOXES = (list, fs) => `<sc-for list="{{${list}}}" as="ob" hint-placeholder-count="3"><span class="sc-occ" style="position: absolute; z-index: {{ob.z}}; left: {{ob.x}}; top: {{ob.y}}; width: {{ob.w}}; height: {{ob.h}}; box-sizing: border-box; border-radius: 6px; background: {{ob.bg}}; color: {{ob.fg}}; box-shadow: {{ob.ring}}; transition: {{ob.tr}}; display: flex; align-items: center; justify-content: center; font-size: ${fs}px; font-weight: 700; line-height: 1;">{{ob.n}}</span></sc-for>`;
// Reduced motion: the box turns to an outline at once.
const OCC_VIEW_CSS = '@media (prefers-reduced-motion:reduce){.sc-occ{transition:none!important}}';
// The editor's corner handles reach further than they look under a finger, mostly outward, so a small box can still
// be moved from its middle. The picture shows it has focus for keyboard use.
const OCC_EDIT_CSS = '.sc-occ-h::before,.sc-occ-x::before{content:"";position:absolute;inset:-5px}'
  + '@media (pointer:coarse){.sc-occ-h[data-occ-h=nw]::before{inset:-16px -3px -3px -16px}.sc-occ-h[data-occ-h=sw]::before{inset:-3px -3px -16px -16px}.sc-occ-h[data-occ-h=se]::before{inset:-3px -16px -16px -3px}.sc-occ-x::before{inset:-10px}}'
  + '.sc-occ-pic:focus-visible{outline:2px solid currentColor;outline-offset:5px}';
const occHandle = (c, pos, cursor) => `<span data-occ-h="${c}" class="sc-occ-h" style="position: absolute; ${pos} width: 12px; height: 12px; box-sizing: border-box; border-radius: 6px; background: {{t.bg}}; box-shadow: 0 0 0 2px {{t.inv}}; cursor: ${cursor};"></span>`;
// The picture in the editor, with its boxes: drag on it to draw one; a picked box shows its corners and a ×. It's h
// tall; with no h (the big editor) it fills the room it's given, and the picture is as big as fits there.
const occPicture = h => `<div style="${h ? `height: ${h}px;` : 'flex: 1 1 0; min-height: 0; container-type: size;'} box-sizing: border-box; padding: 14px; border-radius: 20px; background: {{t.surf}}; display: flex; align-items: center; justify-content: center;">
    <div class="sc-occ-pic" ref="{{occ.ref}}" tabindex="0" role="group" aria-label="The picture. Drag on it to hide a part behind a box." style="position: relative; max-width: 100%; line-height: 0; border-radius: 8px; color: {{t.text}}; touch-action: none; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; cursor: crosshair; outline: 0;">
      <sc-if value="{{img.mock}}" hint-placeholder-val="{{ true }}">${h ? CELL(Math.round((h - 28) * 22 / 15), h - 28, false) : `<div style="width: min(100cqw, 100cqh * 22 / 15); aspect-ratio: 22 / 15;">${CELL('100%', '100%', false, .9)}</div>`}</sc-if>
      <sc-if value="{{img.url}}" hint-placeholder-val="{{ false }}"><img src="{{img.url}}" alt="" draggable="false" style="display: block; ${h ? `max-width: 100%; max-height: ${h - 28}px;` : 'max-width: 100cqw; max-height: 100cqh;'} border-radius: 8px; pointer-events: none;"></sc-if>
      <sc-for list="{{occ.boxes}}" as="b" hint-placeholder-count="3"><div data-occ-box="{{b.id}}" style="position: absolute; z-index: {{b.z}}; left: {{b.x}}; top: {{b.y}}; width: {{b.w}}; height: {{b.h}}; box-sizing: border-box; border-radius: 6px; background: {{b.bg}}; color: {{b.fg}}; box-shadow: {{b.ring}}; display: flex; align-items: center; justify-content: center; font-size: ${h ? 12 : 14}px; font-weight: 700; line-height: 1; cursor: move;">{{b.num}}<sc-if value="{{b.sel}}" hint-placeholder-val="{{ false }}">${occHandle('nw', 'left: -6px; top: -6px;', 'nwse-resize')}${occHandle('sw', 'left: -6px; bottom: -6px;', 'nesw-resize')}${occHandle('se', 'right: -6px; bottom: -6px;', 'nwse-resize')}<button type="button" data-occ-del="1" class="sc-occ-x" onClick="{{b.del}}" aria-label="Remove box {{b.n}}" data-tip="Remove box {{b.n}}" style="position: absolute; {{b.delAt}} width: 24px; height: 24px; padding: 0; border: 0; border-radius: 12px; background: {{t.inv}}; color: {{t.invText}}; box-shadow: 0 0 0 2px {{t.bg}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(I.close, 10, 2.8)}</button></sc-if></div></sc-for>
    </div>
  </div>`;
// One row per box under the picture: its number (tap to pick the box), what's under it (the card's answer), and ×.
const occAnswers = `<sc-if value="{{occ.has}}" hint-placeholder-val="{{ true }}"><div style="display: flex; flex-direction: column; gap: 8px;">
    <span style="font-size: 13px; font-weight: 600;">Answers <span style="font-weight: 400; color: {{t.muted}};">· Each box is its own card. {{occ.hint}}</span></span>
    <div style="display: flex; flex-direction: column; gap: 6px;"><sc-for list="{{occ.boxes}}" as="b" hint-placeholder-count="3"><div style="height: 34px; box-sizing: border-box; padding: 0 6px; display: flex; align-items: center; gap: 8px; border-radius: 14px; background: {{t.surf}}; box-shadow: {{b.rowRing}}; transition: box-shadow .15s;">
      <button type="button" onClick="{{b.pick}}" aria-label="Pick box {{b.n}}" aria-pressed="{{b.pressed}}" style="width: 24px; height: 24px; flex-shrink: 0; padding: 0; border: 0; border-radius: 8px; background: {{b.chip}}; color: {{b.chipFg}}; font: inherit; font-size: 12px; font-weight: 700; cursor: pointer;">{{b.n}}</button>
      <input type="text" value="{{b.label}}" onChange="{{b.setLabel}}" onFocus="{{b.pick}}" onKeyDown="{{b.key}}" data-occ-label="{{b.id}}" placeholder="What’s under box {{b.n}}" aria-label="What’s under box {{b.n}}" maxlength="200" autocomplete="off" style="flex-grow: 1; min-width: 0; height: 100%; padding: 0; border: 0; outline: 0; background: transparent; color: {{t.text}}; font: inherit; font-size: 15px;">
      <button type="button" onClick="{{b.remove}}" aria-label="Remove box {{b.n}}" data-tip="Remove box {{b.n}}" style="width: 28px; height: 28px; flex-shrink: 0; padding: 0; border: 0; border-radius: 14px; background: transparent; color: {{t.muted}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(I.close, 12, 2.2)}</button>
    </div></sc-for></div>
  </div></sc-if>
  <sc-if value="{{occ.tip}}" hint-placeholder-val="{{ false }}"><span style="font-size: 13px; line-height: 1.45; color: {{t.muted}};">Drag on the picture to hide a part behind a box. Each box becomes its own card, with what’s under it as the answer.</span></sc-if>`;
// Card editor: slide-over panel on the deck page
const TYPE_SEG = `<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; padding: 4px; border-radius: 999px; background: {{t.surf}};">
  <sc-for list="{{types}}" as="k" hint-placeholder-count="4">
    <button type="button" onClick="{{k.pick}}" style="height: 36px; border: 0; border-radius: 999px; font: inherit; font-size: 13px; font-weight: 500; cursor: pointer; background: {{k.bg}}; color: {{k.fg}}; box-shadow: {{k.sh}};">{{k.label}}</button>
  </sc-for>
</div>`;
// Card text with its formatting (web/rich.js makes the lines). RICH_SHOW is text on a card; RICH_CLOZE also
// draws blanks, with `pill` as a blank's style; RICH_EDIT is the editor's own drawing, where every letter can be edited.
const RICH_SHOW = e => `<sc-for list="{{${e}}}" as="rl" hint-placeholder-count="1"><div style="{{rl.css}}"><sc-for list="{{rl.items}}" as="rc" hint-placeholder-count="1"><span style="{{rc.css}}">{{rc.t}}</span></sc-for></div></sc-for>`;
const RICH_CLOZE = (e, pill, cls = '') => `<sc-for list="{{${e}}}" as="rl" hint-placeholder-count="1"><div style="{{rl.css}}"><sc-for list="{{rl.items}}" as="rc" hint-placeholder-count="3"><sc-if value="{{rc.plain}}" hint-placeholder-val="{{ true }}"><span style="{{rc.css}}">{{rc.t}}</span></sc-if><sc-if value="{{rc.blank}}" hint-placeholder-val="{{ false }}"><span${cls ? ` class="${cls}"` : ''} style="${pill}"><sc-for list="{{rc.runs}}" as="rr" hint-placeholder-count="1"><span style="{{rr.css}}">{{rr.t}}</span></sc-for></span></sc-if></sc-for></div></sc-for>`;
const RICH_EDIT = e => `<sc-for list="{{${e}}}" as="rl" hint-placeholder-count="1"><div style="{{rl.css}}"><sc-for list="{{rl.items}}" as="rc" hint-placeholder-count="1"><sc-if value="{{rc.plain}}" hint-placeholder-val="{{ true }}"><span data-edge="{{rc.edge}}" style="{{rc.css}}">{{rc.t}}</span></sc-if><sc-if value="{{rc.blank}}" hint-placeholder-val="{{ false }}"><span data-edge="1" style="padding: 1px 10px; border-radius: 999px; background: {{t.inv}}; color: {{t.invText}}; font-weight: 600; -webkit-box-decoration-break: clone; box-decoration-break: clone;"><sc-for list="{{rc.runs}}" as="rr" hint-placeholder-count="1"><span style="{{rr.css}}">{{rr.t}}</span></sc-for></span></sc-if></sc-for><sc-if value="{{rl.empty}}" hint-placeholder-val="{{ false }}"><br></sc-if></div></sc-for>`;
// ---------- Sound: waveforms ----------
// Every sound shows its waveform, like a voice note: bars from the clip's real peaks (web/sound.js measures them once and
// saves them with the card), the part already played in the text color and the rest faint. `v` names a renderVals object
// made by soundView() (SOUND_JS). With `seek` the waveform is a slider: tap or drag on it, or use the arrow keys, to jump
// there. `grow`: it takes the room left in a row (else its box's width).
const waveBars = (v, n) => `<sc-for list="{{${v}.bars}}" as="b" hint-placeholder-count="${n}"><span style="flex: 1 1 0; min-width: 1px; height: {{b.h}}; border-radius: 2px; background: currentColor;"></span></sc-for>`;
const waveRow = (v, n, h, { gap = 2, grow = true, seek = true } = {}) => `<div${seek ? ` ref="{{${v}.ref}}" role="slider" tabindex="0" aria-label="Where to play from" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{${v}.pct}}" aria-valuetext="{{${v}.valueText}}" onClick="{{${v}.hold}}" onKeyDown="{{${v}.keys}}"` : ' aria-hidden="true"'} class="sc-wave" style="position: relative; ${grow ? 'flex-grow: 1; min-width: 0;' : 'width: 100%;'} height: ${h}px; color: {{t.text}};${seek ? ' cursor: pointer; touch-action: pan-y;' : ''}">
  <div style="position: absolute; inset: 0; display: flex; align-items: center; gap: ${gap}px; opacity: .22;">${waveBars(v, n)}</div>
  <div data-anim="1" style="position: absolute; inset: 0; display: flex; align-items: center; gap: ${gap}px; clip-path: {{${v}.fill}}; animation: {{${v}.anim}};">${waveBars(v, n)}</div>
</div>`;
const playGlyph = (v, size) => `<sc-if value="{{${v}.off}}" hint-placeholder-val="{{ true }}">${svg(I.play, size)}</sc-if><sc-if value="{{${v}.on}}" hint-placeholder-val="{{ false }}">${svg(I.pause, size)}</sc-if>`;
const STOP = '<rect x="6.5" y="6.5" width="11" height="11" rx="2.5" fill="currentColor" stroke="none"/>';
// The sample clip's bars, for boards that draw a waveform without a clip (Card types).
const SAMPLE_BARS = n => JSON.stringify(Array.from({ length: n }, (_, i) => {
  const a = Math.floor(i * SAMPLE_WAVE.length / n), b = Math.max(a + 1, Math.floor((i + 1) * SAMPLE_WAVE.length / n));
  return { h: Math.max(9, Math.round(Math.max(...SAMPLE_WAVE.slice(a, b)) * 100)) + '%' };
}));
// A clip's player: `src` is a card or the editor's fields ({ audio, wave } for a sound file, { speak, lang } for words
// read aloud), `n` its number of bars, `slot` which player on the screen. While the clip plays, web/sound.js moves the
// played part and the time every frame, through the refs (the screen redraws only when it starts, pauses, or ends).
const SOUND_JS = `const clock = s => { s = Math.max(0, Math.floor(s || 0)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
  // A clip's length, rounded (a clip under a second still says 0:01).
  const clipLength = d => clock(d > 0 ? Math.max(1, Math.round(d)) : 0);
  const fillTo = f => 'inset(0 ' + ((1 - f) * 100).toFixed(2) + '% 0 0)';
  const soundView = (src, n, slot) => {
    const w = db.sound(src), f = w.frac || 0, dur = w.dur || 0, P = w.peaks && w.peaks.length ? w.peaks : [0];
    const bars = Array.from({ length: n }, (_, i) => { const a = Math.floor(i * P.length / n), b = Math.max(a + 1, Math.floor((i + 1) * P.length / n)); let v = 0; for (let j = a; j < b; j++) v = Math.max(v, P[j] || 0); return { h: Math.max(9, Math.round(v * 100)) + '%' }; });
    const all = this.sounds || (this.sounds = {});
    const h = all[slot] || (all[slot] = {
      wave: el => {
        if (!el) return;
        el.__snd = h;
        h.db.act.watchSound(el, h.key, x => { const p = el.lastElementChild; if (p) p.style.clipPath = fillTo(x); });
        if (el.__sndOn) return;
        el.__sndOn = true;
        // Tap or drag: the waveform follows the finger, and letting go moves the sound there.
        let drag = false;
        const at = e => { const r = el.getBoundingClientRect(); return r.width ? Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)) : 0; };
        const go = (x, dragging) => { const s = el.__snd; s.db.act.seekSound(s.src, x, dragging); };
        el.addEventListener('pointerdown', e => { if (e.button > 0) return; drag = true; try { el.setPointerCapture(e.pointerId); } catch (err) { /* already let go */ } go(at(e), true); });
        el.addEventListener('pointermove', e => { if (drag) go(at(e), true); });
        el.addEventListener('pointerup', e => { if (drag) { drag = false; go(at(e), false); } });
        el.addEventListener('pointercancel', () => { if (drag) { drag = false; go(null, false); } });
      },
      at: el => { if (el) h.db.act.watchSound(el, h.key, (x, sec) => { el.textContent = clock(sec); }); },
      time: el => { if (el) h.db.act.watchSound(el, h.key, (x, sec, d, on) => { el.textContent = x > 0 || on ? clock(sec) : clipLength(d); }); }
    });
    Object.assign(h, { db, src, key: w.key, dur });
    return { key: w.key, bars, fill: fillTo(f), anim: 'none', on: w.on, off: !w.on, hasTime: !w.speech && dur > 0,
      label: w.on ? 'Pause' : 'Play the sound', word: w.on ? 'Pause' : 'Play',
      at: clock(f * dur), total: clipLength(dur), time: f > 0 || w.on ? clock(f * dur) : clipLength(dur),
      pct: String(Math.round(f * 100)), valueText: w.speech ? Math.round(f * 100) + '%' : clock(f * dur) + ' of ' + clipLength(dur),
      toggle: e => { if (e && e.stopPropagation) e.stopPropagation(); h.db.act.playSound(h.src); },
      hold: e => { if (e && e.stopPropagation) e.stopPropagation(); },
      // ← and → move a second (or a twentieth of the words), Home and End go to either end, Space or Return plays or pauses.
      keys: e => {
        const x = h.db.sound(h.src).frac || 0, step = h.dur ? Math.min(.25, 1 / h.dur) : .05;
        const to = { ArrowLeft: x - step, ArrowRight: x + step, Home: 0, End: 1 }[e.key];
        if (to != null) { e.preventDefault(); h.db.act.seekSound(h.src, Math.min(1, Math.max(0, to)), false); }
        else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); h.db.act.playSound(h.src); }
      },
      ref: h.wave, atRef: h.at, timeRef: h.time };
  };`;
// Waveforms: a ring for the keyboard, bars that settle into a clip's shape when it arrives, and pressing a player inside
// a flip card doesn't press the card. The dot beside a recording's time pulses (not with reduced motion).
const WAVE_CSS = '.sc-wave{outline:0;-webkit-tap-highlight-color:transparent}.sc-wave:focus-visible{box-shadow:0 0 0 2px currentColor;border-radius:8px}.sc-wave span{transition:height .35s cubic-bezier(.2,.8,.2,1)}'
  + 'button:has(.sc-hold:active,.sc-wave:active){transform:none}'
  + '@keyframes scRecDot{50%{opacity:.25}}.sc-rec-dot{animation:scRecDot 1.2s ease-in-out infinite}'
  + '@keyframes scPlayed{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}'
  + '@media (prefers-reduced-motion:reduce){.sc-wave span{transition:none}.sc-rec-dot{animation:none}}';
// An empty field shows its placeholder.
const RICH_CSS = '.sc-rich[data-empty="true"]::before{content:attr(data-ph);position:absolute;color:var(--ph);pointer-events:none}' + WAVE_CSS;
// A card field: it shows bold, blanks, and the rest as you type. The editor's logic handles every keystroke.
// A big one (the big editor) fills the height it's given, in bigger type.
const field = (label, key, rows = 3, ph = '', big = false) => `<div style="${big ? 'flex: 1 1 0; min-height: 0; ' : ''}display: flex; flex-direction: column; gap: 8px;"><span style="font-size: 13px; font-weight: 600;">${label}</span><div class="sc-rich" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${label}" spellcheck="true" data-rk="${key}" data-ph="${ph}" data-empty="{{rich.${key}.empty}}" key="{{rich.${key}.key}}" ref="{{rich.${key}.ref}}" style="position: relative; ${big ? 'flex-grow: 1; ' : ''}min-height: ${+(rows * 1.45).toFixed(2)}em; ${big ? '' : 'max-height: 14.5em; '}overflow-y: auto; border-radius: 20px; padding: ${big ? '18px 20px' : '14px 16px'}; background: {{t.surf}}; color: {{t.text}}; box-shadow: {{rich.${key}.ring}}; outline: 0; font-size: ${big ? 20 : 15}px; line-height: 1.45; white-space: pre-wrap; overflow-wrap: break-word; --ph: {{t.muted}}; transition: box-shadow .15s;">${RICH_EDIT(`rich.${key}.lines`)}</div></div>`;
const blankPill = word => `<span style="padding: 1px 10px; border-radius: 999px; background: {{t.inv}}; color: {{t.invText}}; font-weight: 600;">${word}</span>`;
// The fields for each kind of card, in one column. The big editor (big) sets each kind out in two columns instead: the
// front and the back side by side (a blank card's text and what's shown after it, a sound and its answer), or the
// picture as big as it fits, with its answers beside it (`side` wide).
// A card made from one of the deck's sources says so, and the line opens that source at the card's place (its page, or its time).
const madeFromLine = phone => { const st = `align-self: flex-start; max-width: 100%; box-sizing: border-box; min-height: ${phone ? 44 : 32}px; padding: 0 14px 0 12px; display: inline-flex; align-items: center; gap: 8px; border-radius: 999px; background: {{t.surf}}; color: {{t.muted}}; font-size: 13px; font-weight: 500;`,
  inner = `<span style="display: flex; flex-shrink: 0;">${svg(I.file, 14, 1.8)}</span><span style="min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">{{madeFrom.label}}</span>`;
  return `<sc-if value="{{madeFrom.link}}" hint-placeholder-val="{{ true }}"><a href="{{madeFrom.href}}" aria-label="{{madeFrom.label}}" style="${st}">${inner}</a></sc-if><sc-if value="{{madeFrom.plain}}" hint-placeholder-val="{{ false }}"><span style="${st}">${inner}</span></sc-if>`; };
const editorFieldsOf = (phone, big = false, side = 380) => {
  const col = 'min-height: 0; display: flex; flex-direction: column; gap: 20px;', picH = big ? 0 : phone ? 240 : 186, waveH = big ? 96 : 32;
  const two = (main, side, cols = 'repeat(2, minmax(0, 1fr))') => big ? `<div style="flex: 1 1 0; min-height: 0; display: grid; grid-template-columns: ${cols}; grid-template-rows: minmax(0, 1fr); gap: 28px;"><div style="${col}">${main}</div><div style="${col} overflow-y: auto; scrollbar-width: thin;">${side}</div></div>` : main + side;
  return `
<sc-if value="{{isBasic}}" hint-placeholder-val="{{ true }}">${two(field('Front', 'front', 3, 'The question', big), field('Back', 'back', 2, 'The answer', big))}</sc-if>
<sc-if value="{{isCloze}}" hint-placeholder-val="{{ false }}">${two(field('Text', 'text', 3, 'Put [[double brackets]] around the words to hide', big), `
  <div style="display: flex; flex-direction: column; gap: 8px;"><span style="font-size: 13px; font-weight: 600;">Cards to make</span>${panelSeg('clozeModes', 'Cards to make')}</div>
  ${field('Extra, shown after', 'note', 1, '', big)}`)}</sc-if>
<sc-if value="{{isImage}}" hint-placeholder-val="{{ false }}">${two(`<sc-if value="{{img.some}}" hint-placeholder-val="{{ true }}">${occPicture(picH)}</sc-if>
  <sc-if value="{{img.none}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{pickImage}}" style="${picH ? `height: ${picH}px;` : 'flex: 1 1 0; min-height: 0;'} border: 1.5px dashed {{t.muted}}; border-radius: 20px; background: transparent; color: {{t.muted}}; font: inherit; font-size: 14px; font-weight: 600; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; cursor: pointer;">${svg(I.image, 22, 1.8)}Add an image</button></sc-if>
  <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">${smallBtn('Replace image', 'pickImage', 'image')}<sc-if value="{{occ.canAdd}}" hint-placeholder-val="{{ true }}">${smallBtn('Add a box', 'addBox', 'plus')}</sc-if><sc-if value="{{occ.has}}" hint-placeholder-val="{{ true }}"><span style="flex-grow: 1;"></span>${panelSeg('occModes', 'What to hide')}</sc-if></div>`, `
  ${occAnswers}
  ${field('Prompt', 'front', 1, 'What should they name?')}<sc-if value="{{occ.none}}" hint-placeholder-val="{{ false }}">${field('Answer', 'back', 1)}</sc-if>`, `minmax(0, 1fr) ${side}px`)}</sc-if>
<sc-if value="{{isAudio}}" hint-placeholder-val="{{ false }}">${two(`<div style="${big ? 'flex: 1 1 0; min-height: 0;' : 'height: 72px;'} box-sizing: border-box; border-radius: 20px; background: {{rec.bg}}; display: flex; align-items: center; gap: 14px; padding: 0 16px; transition: background-color .2s;">
  <sc-if value="{{rec.show}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{toggleRecord}}" aria-label="{{rec.label}}" style="width: 40px; height: 40px; flex-shrink: 0; padding: 0; border: 0; border-radius: 20px; background: {{rec.btn}}; color: #FFFFFF; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(STOP, 16)}</button><div ref="{{rec.ref}}" aria-hidden="true" style="flex-grow: 1; min-width: 0; height: ${waveH}px; overflow: hidden; display: flex; justify-content: flex-end;"><div style="flex-shrink: 0; height: 100%; display: flex; align-items: center; gap: 2px;"><sc-for list="{{rec.bars}}" as="b" hint-placeholder-count="71"><span style="width: 3px; flex-shrink: 0; height: {{b.h}}; border-radius: 2px; background: {{t.text}};"></span></sc-for></div></div><span role="timer" aria-label="Recording time" style="flex-shrink: 0; display: flex; align-items: center; gap: 6px; font-family: ${MONO}; font-size: 12px; color: {{rec.ink}};"><sc-if value="{{rec.on}}" hint-placeholder-val="{{ true }}"><span class="sc-rec-dot" style="width: 7px; height: 7px; border-radius: 4px; background: {{t.again}};"></span></sc-if><span ref="{{rec.timeRef}}">{{rec.time}}</span></span></sc-if>
  <sc-if value="{{snd.show}}" hint-placeholder-val="{{ true }}"><button type="button" onClick="{{snd.toggle}}" aria-label="{{snd.label}}" style="width: 40px; height: 40px; flex-shrink: 0; padding: 0; border: 0; border-radius: 20px; background: {{t.inv}}; color: {{t.invText}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${playGlyph('snd', 16)}</button>${waveRow('snd', 56, waveH)}<sc-if value="{{snd.hasTime}}" hint-placeholder-val="{{ true }}"><span ref="{{snd.timeRef}}" style="flex-shrink: 0; min-width: 30px; text-align: right; font-family: ${MONO}; font-size: 12px; color: {{t.muted}};">{{snd.time}}</span></sc-if></sc-if>
  <sc-if value="{{snd.none}}" hint-placeholder-val="{{ false }}"><span aria-hidden="true" style="width: 40px; height: 40px; flex-shrink: 0; border-radius: 20px; background: {{t.surf2}}; color: {{t.muted}}; display: flex; align-items: center; justify-content: center;">${svg(I.play, 16)}</span><span style="flex-grow: 1; min-width: 0; font-size: 14px; color: {{t.muted}}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">No sound yet. Record one, upload a file, or have it read aloud.</span></sc-if></div>
  <div style="display: flex; gap: 8px; flex-wrap: wrap;">${smallBtn('{{recLabel}}', 'toggleRecord', 'mic')}${smallBtn('Upload', 'pickAudio', 'upload')}${smallBtn('Read it aloud', 'toggleSpeak', 'audio')}</div>
  <sc-if value="{{speakOn}}" hint-placeholder-val="{{ false }}">${field('Words to read aloud', 'speak', 1, 'What the card says out loud')}</sc-if>`, `
  ${field('Answer', 'back', 1, '', big)}
  <div style="display: flex; align-items: center; gap: 12px; min-height: 44px;"><span style="flex-grow: 1; display: flex; flex-direction: column; gap: 2px;"><span style="font-size: 14px; font-weight: 600;">Play on its own</span><span style="font-size: 12px; color: {{t.muted}};">The sound starts when the card comes up</span></span>${SWITCH('autoSw', 'toggleAuto', 'Play on its own')}</div>`)}</sc-if>`;
};
// Web formatting bar: text styles, blank, list, math, image, audio, undo. It works on the field you're typing in,
