  const shown = all.filter(x => (kf === 'all' || x.c.kind === kf) && (!tf || (x.c.tags || []).includes(tf)) && (!q || [x.front, x.back, ...(x.c.tags || [])].join(' ').toLowerCase().includes(q))), ids = shown.map(x => x.id);
