  const words = o.box ? '' : `<div style="height: 100%; display: flex; flex-direction: column; justify-content: center; font-size: ${o.fs ?? 36}px; font-weight: ${o.fw ?? 500}; line-height: 1.2; letter-spacing: -.02em; ${o.wcss ?? ''}">${o.text ?? o.html}</div>`;
