// Themes (Pro): Settings › Theme (web and iPhone, on Pro and on Free), each theme's page, and the Themes page of the
// canvas: every theme on the real screens (web Library, flashcards, Learn mode, and deck page; iPhone flashcards and
// Settings, for the profile picture). Each board carries its themes' code, CSS, and fonts (design/themes.mjs).
const PLAN_PROP = { editor: 'enum', default: 'Pro', options: ['Free', 'Pro', 'Pro, ending'] };
const THEME_PROP = { editor: 'enum', default: 'hose', options: ['lucida', ...THEME_KEYS] };
const ALL = { css: themeCss(THEME_KEYS), fonts: themeFonts(THEME_KEYS) };
Object.assign(files, {
  'ThemePicker': ['Web · Settings › Theme', themePicker, { props: { ...DARK, grain: MESH('Iris').grain, plan: PLAN_PROP, theme: THEME_PROP }, logic: withThemes(THEME_KEYS, themePickerLogic(false)), ...ALL, w: W, h: H }],
  'ThemePickerFree': ['Web · Settings › Theme · on Free (locked, Go Pro)', themeOf('ThemePicker', W, H, 'plan="Free" theme="lucida"'), { logic: withThemes(THEME_KEYS, darkLogic), ...ALL, w: W, h: H }],
  'ThemePickerDark': ['Web · Settings › Theme (dark)', darkOf('ThemePicker', W, H), { logic: withThemes(THEME_KEYS, darkLogic), ...ALL, w: W, h: H }],
  'PhoneThemePicker': ['iPhone · Settings › Theme', phoneThemePicker, { props: { ...DARK, grain: MESH('Iris').grain, plan: PLAN_PROP, theme: THEME_PROP }, logic: withThemes(THEME_KEYS, themePickerLogic(true)), ...ALL, w: PW, h: PHONE_THEMES_H }],
  'PhoneThemePickerFree': ['iPhone · Settings › Theme · on Free (locked, Go Pro)', themeOf('PhoneThemePicker', PW, PHONE_THEMES_H, 'plan="Free" theme="lucida"'), { logic: withThemes(THEME_KEYS, darkLogic), ...ALL, w: PW, h: PHONE_THEMES_H }],
  'WebTheme': ['Web · Settings › Theme › Lucida (a theme’s page)', webTheme, { props: { ...DARK, grain: MESH('Iris').grain, plan: PLAN_PROP, sheet: { editor: 'string', default: '' } }, logic: themePageLogic(false), w: W, h: H }],
  'PhoneTheme': ['iPhone · Settings › Theme › a theme’s page', phoneTheme, { props: { ...DARK, grain: MESH('Iris').grain, plan: PLAN_PROP, sheet: { editor: 'string', default: 'aero' } }, logic: withThemes(['aero'], themePageLogic(true)), css: themeCss(['aero']), fonts: themeFonts(['aero']), w: PW, h: PHONE_THEME_H }],
});
for (const T of THEMES.filter(x => x.key !== 'lucida')) {
  const k = T.key, B = 'Theme' + T.board, one = { css: themeCss([k]), fonts: themeFonts([k]) }, logic = withThemes([k], darkLogic), at = attrs => `skin="${k}" ${attrs}`.trim();
  Object.assign(files, {
    [B]: [`${T.name} · Settings › Theme › its page`, themeOf('WebTheme', W, H, `sheet="${k}"`), { logic, ...one, w: W, h: H }],
    [B + 'Free']: [`${T.name} · its page on Free (Go Pro)`, themeOf('WebTheme', W, H, `sheet="${k}" plan="Free"`), { logic, ...one, w: W, h: H }],
    [B + 'Library']: [`${T.name} · Web · Library`, themeOf('WebDecks', W, H, at('')), { logic, ...one, css: one.css + DRAG_CSS, w: W, h: H }],
    [B + 'Review']: [`${T.name} · Web · Flashcards`, themeOf('WebReview', W, H, at('start-revealed="{{yes}}"')), { logic, ...one, css: one.css + REVIEW_CSS, w: W, h: H }],
    [B + 'Learn']: [`${T.name} · Web · Learn mode`, themeOf('WebQuiz', W, H, at('answered="{{yes}}"')), { logic, ...one, css: one.css + LEARN_CSS, w: W, h: H }],
    [B + 'Deck']: [`${T.name} · Web · Deck page`, themeOf('WebDeck', W, H, at('')), { logic, ...one, css: one.css + NUM_CSS + PARALLAX_CSS + DRAG_CSS, w: W, h: H }],
    [B + 'ReviewPhone']: [`${T.name} · iPhone · Flashcards`, themeOf('PhoneReview', PW, PH, at('start-revealed="{{yes}}"')), { logic, ...one, css: one.css + REVIEW_CSS, w: PW, h: PH }],
    [B + 'ProfilePhone']: [`${T.name} · iPhone · Settings (your profile picture)`, themeOf('PhoneSettings', PW, PH, at('')), { logic, ...one, w: PW, h: PH }],
  });
}
Object.assign(files, siteFiles());
// Making cards from anything, a deck's Guide, and its Sources (design/materials.mjs; web/make.js, web/guide.js).
Object.assign(files, makeBoards({ svg, I, FONT, MONO, T, DB_JS, DARK, MESH, W, HH: H, PW, PH, sidebar, OCC }));
// The questions that ask before something is deleted or left (design/ui.mjs): each board that asks one shows it open through its `ask` Tweak, drawn
// over the whole board, with the words the app puts in the same dialog. (The app draws its own over any page: web/ui.js.)
const ASKS = {
  WebDeck: ['Delete deck', 'Remove from library', 'Delete source'], PhoneDeck: ['Delete deck', 'Remove from library', 'Delete source'],
  WebDecks: ['Remove folder'], PhoneLibrary: ['Remove folder'],
  WebCardsScreen: ['Delete card', 'Leave without saving'], PhoneEditor: ['Delete card'],
  WebSettings: ['Delete my data'], PhoneSettings: ['Sign out'],
  WebGuide: ['Delete page'], PhoneGuide: ['Delete page'],
  WebConnect: ['Disconnect app', 'New link'], PhoneConnect: ['Disconnect app', 'New link']
};
for (const [name, list] of Object.entries(ASKS)) {
  const f = files[name];
  if (!f) throw new Error('design/build.mjs: ASKS names a board that does not exist: ' + name);
  const opts = f[2], root = /^<div[^>]*?style="([^"]*)"/.exec(f[1].trimStart());
  if (!root || !f[1].includes('</div>')) throw new Error('design/build.mjs: ' + name + ' has no root box to draw a question in');
  // The question goes at the end of the board's page, over the rest of it (the page's box has to be positioned for that).
  const body = /position:\s*(relative|absolute)/.test(root[1]) ? f[1] : f[1].replace(root[0], root[0].replace('style="', 'style="position: relative; ')), last = body.lastIndexOf('</div>');
  f[1] = body.slice(0, last) + askMarkup({ phone: opts.w === 390, layer: 'absolute' }) + body.slice(last);
  const samples = JSON.stringify(Object.fromEntries(list.map(k => [k, ASK_SAMPLES[k]])));
  if (!opts.logic.includes('renderVals() {')) throw new Error('design/build.mjs: ' + name + ' has no renderVals to add a question to');
  f[2] = { ...opts, props: { ...opts.props, ask: askProp(list) },
    logic: opts.logic.replace('renderVals() {', `${name === 'WebDeck' || name === 'PhoneDeck' ? PLAYER_JS + '\n' : ''}renderVals() { const v = this.renderVals0(); return { ...v, ask: this.askPreview(v.t || this.theme(!!this.props.dark, !!this.props.dim), ${samples}) }; }\n${ASK_JS}\nrenderVals0() {`) };
}
// The canvas keeps what every board shares once, in three files beside the boards (design/slim.mjs): the logic every board
// has, the themes' code and the CSS every board starts with. Each board keeps its own markup, props and logic.
const { slimBoards } = await import('./slim.mjs');
const slim = slimBoards(Object.entries(files).map(([name, [title, body, opts]]) => [name, page(title, body, opts), opts]), { rich: RICH_METHOD, drag: DRAG_METHOD, tip: TIP_SRC });
for (const [name, text] of slim.boards) writeFileSync(OUT + name + '.dc.html', text);
for (const [file, text] of Object.entries(slim.files)) writeFileSync(OUT + file, text);

// The canvas layout (where each board sits) lives in canvas/project/canvas.json. It's kept in sync with the live
// canvas, since boards can be moved there, so this script never rewrites it.
console.log(Object.keys(files).length, 'artboards');
